n=16
walls={(0,7),(1,8),(2,5),(2,9),(3,6),(3,10),(4,7),(4,11),(5,8),(5,12),(6,4),(6,9),(6,13),(7,5),(7,10),(7,14),(8,6),(8,11),(8,15),(9,7),(9,12),(10,8),(10,13),(11,4),(11,9),(12,5)}
seen=set(); q=deque()
for r in range(n):
 for c in range(n):
  if (r,c) not in walls and (r in (0,n-1) or c in (0,n-1)): seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if 0<=p[0]<n and 0<=p[1]<n and p not in seen and p not in walls: seen.add(p);q.append(p)
interior={(r,c) for r in range(n) for c in range(n) if (r,c) not in seen and (r,c) not in walls}
print('components interior', sorted(interior))
print([ (r,sorted(c for rr,c in interior if rr==r)) for r in range(n) if any(rr==r for rr,c in interior)])

def hull(points):
 pts=sorted(set((c,r) for r,c in points))
 def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
 lo=[]
 for p in pts:
  while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
  lo.append(p)
 up=[]
 for p in reversed(pts):
  while len(up)>=2 and cross(up[-2],up[-1],p)<=0: up.pop()
  up.append(p)
 return lo[:-1]+up[:-1]
